python3 -m py_compile src/services/billing.py && python3 - <<'EOF'
import src.services.billing as billing

class Invoice:
    id = "INV-1"
    amount_due = 100
    currency = "EUR"

class GatewayResult:
    def __init__(self, succeeded, transaction_id=None, error_code=None):
        self.succeeded = succeeded
        self.transaction_id = transaction_id
        self.error_code = error_code

class Gateway:
    def __init__(self, result):
        self.result = result
    def charge(self, amount, currency):
        assert amount == 100 and currency == "EUR"
        return self.result

class Repository:
    def __init__(self):
        self.saved = None
    def save_invoice_status(self, invoice_id, status, transaction_id=None, error_code=None):
        self.saved = (invoice_id, status, transaction_id, error_code)

ok = billing.charge_invoice(Invoice(), Gateway(GatewayResult(True, transaction_id="T1")), Repository())
fail = billing.charge_invoice(Invoice(), Gateway(GatewayResult(False, error_code="E1")), Repository())
assert ok.succeeded and fail.error_code == "E1"
print("runtime OK")
EOF
